    print('%d Hz infrasound wavelength: %.2f m' % (f, v / f))

def ndsi(bio, anth):
    return (bio - anth) / (bio + anth)
for bio, anth in ((0.8, 0.2), (0.2, 0.8), (0.5, 0.5)):
    print('Bio %.1f, anth %.1f: NDSI %.2f' % (bio, anth, ndsi(bio, anth)))
